#include <iostream>
#include <string>
#include <filesystem>
#include <vector>
#include <map>
#include <sstream>
#include <algorithm>
#include <functional>
#include <memory>

namespace fs = std::filesystem;

struct TenantConfig {
    std::string tenant_id;
    std::string base_path;
    bool allow_listing;
    std::vector<std::string> allowed_extensions;
};

static std::string html_escape(const std::string& input) {
    std::string out;
    out.reserve(input.size());
    for (char c : input) {
        switch (c) {
            case '&':  out += "&amp;";  break;
            case '<':  out += "&lt;";   break;
            case '>':  out += "&gt;";   break;
            case '"':  out += "&quot;"; break;
            case '\'': out += "&#39;";  break;
            default:   out += c;         break;
        }
    }
    return out;
}

class PathNormalizer {
public:
    static std::string normalize(const std::string& path) {
        std::string result;
        result.reserve(path.size());
        bool last_was_slash = false;
        for (char c : path) {
            if (c == '\\') c = '/';
            if (c == '/' && last_was_slash) continue;
            last_was_slash = (c == '/');
            result += c;
        }
        return result;
    }

    static bool contains_traversal(const std::string& path) {
        std::string normalized = normalize(path);
        if (normalized.find("..") != std::string::npos) return true;
        return false;
    }
};

class TenantIsolationLayer {
private:
    std::map<std::string, TenantConfig> tenants_;

    bool is_within_tenant_boundary(const std::string& resolved_path, const std::string& tenant_base) {
        std::string canonical_base = fs::weakly_canonical(tenant_base).string();
        std::string canonical_path = fs::weakly_canonical(resolved_path).string();
        // Ensure the path starts with the base AND is followed by '/' or is exactly the base
        if (canonical_path.size() < canonical_base.size()) return false;
        if (canonical_path.substr(0, canonical_base.size()) != canonical_base) return false;
        if (canonical_path.size() > canonical_base.size() && canonical_path[canonical_base.size()] != '/') return false;
        return true;
    }

public:
    void register_tenant(const TenantConfig& config) {
        tenants_[config.tenant_id] = config;
    }

    const TenantConfig* get_tenant(const std::string& tenant_id) const {
        auto it = tenants_.find(tenant_id);
        if (it == tenants_.end()) return nullptr;
        return &it->second;
    }

    bool validate_access(const std::string& tenant_id, const std::string& requested_path) {
        auto* config = get_tenant(tenant_id);
        if (!config) return false;
        std::string full_path = config->base_path + "/" + requested_path;
        return is_within_tenant_boundary(full_path, config->base_path);
    }
};

class DirectoryListingService {
private:
    TenantIsolationLayer& isolation_;

    std::string generate_listing(const std::string& dir_path, const TenantConfig& config) {
        std::ostringstream html;
        html << "<html><body><h2>Directory: " << html_escape(dir_path) << "</h2><ul>";

        for (const auto& entry : fs::directory_iterator(dir_path)) {
            std::string name = entry.path().filename().string();
            std::string safe_name = html_escape(name);
            if (entry.is_directory()) {
                html << "<li><a href=\"" << safe_name << "/\">" << safe_name << "/</a></li>";
            } else {
                std::string ext = entry.path().extension().string();
                if (config.allowed_extensions.empty() || 
                    std::find(config.allowed_extensions.begin(), 
                             config.allowed_extensions.end(), ext) != config.allowed_extensions.end()) {
                    html << "<li><a href=\"" << safe_name << "\">" << safe_name << "</a></li>";
                }
            }
        }
        html << "</ul></body></html>";
        return html.str();
    }

public:
    DirectoryListingService(TenantIsolationLayer& isolation) : isolation_(isolation) {}

    std::string handle_request(const std::string& tenant_id, const std::string& raw_path) {
        const TenantConfig* config = isolation_.get_tenant(tenant_id);
        if (!config) return "<html><body>403 Forbidden</body></html>";

        if (PathNormalizer::contains_traversal(raw_path)) {
            return "<html><body>400 Bad Request</body></html>";
        }

        std::string normalized = PathNormalizer::normalize(raw_path);

        if (!isolation_.validate_access(tenant_id, normalized)) {
            return "<html><body>403 Forbidden</body></html>";
        }

        std::string full_path = config->base_path + "/" + normalized;

        if (!fs::exists(full_path)) {
            return "<html><body>404 Not Found</body></html>";
        }

        if (fs::is_directory(full_path)) {
            if (!config->allow_listing) {
                return "<html><body>403 Directory listing disabled</body></html>";
            }
            return generate_listing(full_path, *config);
        }

        return "<html><body>File content served here</body></html>";
    }
};

class MultiTenantWebServer {
private:
    TenantIsolationLayer isolation_;
    DirectoryListingService listing_service_;

    std::pair<std::string, std::string> extract_tenant_and_path(const std::string& url) {
        std::string normalized_url = PathNormalizer::normalize(url);
        if (normalized_url.empty() || normalized_url[0] != '/') {
            return {"", ""};
        }

        size_t second_slash = normalized_url.find('/', 1);
        std::string tenant_id;
        std::string path;

        if (second_slash == std::string::npos) {
            tenant_id = normalized_url.substr(1);
            path = "";
        } else {
            tenant_id = normalized_url.substr(1, second_slash - 1);
            path = normalized_url.substr(second_slash + 1);
        }
        return {tenant_id, path};
    }

public:
    MultiTenantWebServer() : listing_service_(isolation_) {}

    void add_tenant(const TenantConfig& config) {
        isolation_.register_tenant(config);
    }

    std::string process_request(const std::string& method, const std::string& url) {
        if (method != "GET") {
            return "<html><body>405 Method Not Allowed</body></html>";
        }

        auto [tenant_id, path] = extract_tenant_and_path(url);

        if (tenant_id.empty()) {
            return "<html><body>400 Bad Request</body></html>";
        }

        return listing_service_.handle_request(tenant_id, path);
    }
};

int main() {
    MultiTenantWebServer server;

    TenantConfig tenant_a{"acme", "/srv/tenants/acme/public", true, {".html", ".css", ".js"}};
    TenantConfig tenant_b{"globex", "/srv/tenants/globex/public", false, {}};

    server.add_tenant(tenant_a);
    server.add_tenant(tenant_b);

    std::string response = server.process_request("GET", "/acme/docs");
    std::cout << response << std::endl;

    return 0;
}
